// ================= ★ Riverfront Times Square (京基滨河时代广场; Zhubo Design with LLA; developer Kingkey; 2012-2016) =================
// 293 m architectural = tip = helipad, 64 floors above ground, hotel / office, concrete-steel composite, 24 lifts (CTBUH 14617, complex
// 4316: with three 157-158 m, 45-storey residential towers of 2014). Zhubo (co188): offices and hotel in cool-toned glass curtain walls,
// the apartments and shops in warm stone. Footprint OSM w349913546 (height tag 293): a 65 x 43 m plan whose four sides each fold once
// (faceted) with rounded corners. Modelled on that plan: cool blue-grey glass with vertical fins every 3 m and floor lines every 4.2 m, two
// refuge bands, the roof at 281 m (estimate) with a 6 m glass parapet, a raised core volume and the helipad deck at 293 m. The roof level,
// fin module, refuge levels and the crown's form are estimates (no source describes the top).
LANDMARKS.szriverfront = {zh:'京基滨河时代广场', en:'Riverfront Times Square', cat:'new', r:44, h:293, lt:nightLt(0.65),
  build(){
    const g = new THREE.Group(), B = mkB(), T = D.szriverfront.T, roof = 281, yl = 14;
    const GL = {c:'#6d8a9c', m:1, fh:4.2, cw:1.5}, FIN = {c:'#cdd5d9', m:0, lk:0.4, lc:'#eef4ff'}, SPN = {c:'#9eacb3', m:0, lk:0.2},
      MECH = {c:'#4c5961', m:0, lk:0.15}, SCR = {c:'#9cb3c1', glow:'#e2ecf8', gk:0.35}, DECK = {c:'#8d9396', m:0, lk:0.3};
    foot(B, T, yl);
    finsP(B.p(FIN), offP(T, 1.2), 0.4, yl, 6, 0.4, 0.3, 1);
    shaft(B, T, yl, roof, {gl:GL, mul:FIN, mstep:3, md:0.5, mw:0.12, sp:SPN, fh:4.2, bh:0.4, boff:0.1});
    for (const y of [yl + 4.2*21, yl + 4.2*42]) prism(B.p(MECH), offP(T, -0.3), y - 1.4, y + 1.4, false);
    flat(B.p(ROOFC), offP(T, 0.4), roof);
    prism(B.p(SCR), T, roof, roof + 6, false); finsP(B.p(FIN), T, roof, roof + 6, 3, 0.4, 0.1, 0.5); prism(B.p(CAP), offP(T, -0.2), roof + 5.3, roof + 6, false);
    const C = offP(T, 9); prism(B.p(GL), C, roof, 290.5, false); finsP(B.p(FIN), C, roof, 290.5, 3, 0.35, 0.1, 0.5); flat(B.p(ROOFC), C, 290.5);
    const DK = roundP(rectP(-12, -12, 12, 12), 4, 3), o = B.p(DECK);
    for (const [x, z] of [[-8, -8], [8, -8], [8, 8], [-8, 8]]) abox(o, x - 0.6, x + 0.6, 290.5, 292, z - 0.6, z + 0.6);
    prism(o, DK, 292, 293, true, true);
    const hp = []; for (let i = 0; i < 16; i++){ const a = i/16*TAU; hp.push(Math.cos(a)*11.5, 293.3, Math.sin(a)*11.5); }
    const sp = redLights(B, g, cornersAt(T, roof + 6, 1.2).filter((p, i) => i % 6 === 0));
    B.flush(g); sprites(g, sp, AVL, 8); sprites(g, hp, [0.9, 0.95, 1], 3.5);
    return g;
  }};
place('szriverfront');

// ================= medium-detail towers: one builder, a spec per key (the sz50a stdTower, with residential options) =================
// S: zh en H roof yl fh gl mul ms md sp (facade specs) crown(B, P, S, g, roof) extra(B, P, S, g, roof) pod (height of the other target
// pieces, default their app height) lt; facade colours and crowns are estimates unless the section says otherwise.
function stdTower(key, S){
  LANDMARKS[key] = {zh:S.zh, en:S.en, cat:'new', r:S.r || 45, h:S.H, lt:S.lt || nightLt(0.6),
    build(){
      const g = new THREE.Group(), B = mkB(), E = D[key], T = S.plan ? S.plan(E.T) : E.T, H = S.H, roof = S.roof || H - 3, yl = S.yl || 9;
      foot(B, S.lowIn ? offP(T, S.lowIn) : T, yl, S.stone, S.inset);
      shaft(B, T, yl, roof, {gl:S.gl, mul:S.mul, mstep:S.ms || 3, md:S.md, mw:S.mw, sp:S.sp, fh:S.fh || 4.2, bh:S.bh || 0.5, boff:S.boff});
      if (S.mech) for (const y of S.mech) prism(B.p({c:'#4f5b62', m:0, lk:0.15}), offP(T, -0.3), y - 1.2, y + 1.2, false);
      if (S.crown) S.crown(B, T, S, g, roof);
      else roofTop(B, T, roof, Math.max(roof + 1.2, H), 5, Math.min(4.5, H - roof - 0.2 > 0 ? H - roof - 0.2 : 3.5));
      for (const [h0, R] of (E.X || [])){ const h = S.pod !== undefined ? S.pod : h0;
        prism(B.p(STONE), offP(R, -0.2), -5, 0.4);
        prism(B.p(S.podGl || {c:'#566770', m:1, fh:4.5, cw:3.0}), offP(R, 0.4), 0.4, h - 2.2, false);
        prism(B.p(S.podCap || CAP), R, h - 2.2, h, false); flat(B.p(ROOFC), R, h); }
      if (S.extra) S.extra(B, T, S, g, roof);
      const sp = redLights(B, g, S.lights ? S.lights(T, roof) : cornersAt(T, Math.max(roof + 1.2, H), 1.2).filter((p, i, A) => A.length < 9 || i % Math.ceil(A.length/6) === 0));
      B.flush(g); sprites(g, sp, AVL, 8);
      return g;
    }};
  place(key);
}
const screenCrown = (spec, bs) => (B, P, S, g, roof) => {
  flat(B.p(ROOFC), offP(P, 0.4), roof); prism(B.p(PLANT), offP(P, 3), roof, roof + Math.min(8, S.H - roof - 1));
  prism(B.p(S.sp || CAP), P, roof - 0.5, roof + 0.6, false);
  finsP(B.p(spec), P, roof + 0.6, S.H, bs || 1.5, 0.5, 0.14, 0.2);
  prism(B.p(spec), offP(P, -0.15), S.H - 0.9, S.H, false);
};
const stepCrown = (gl, d, n) => (B, P, S, g, roof) => {
  let y = roof; const dy = (S.H - roof)/n;
  for (let i = 0; i < n; i++){ const Q = offP(P, d*(i + 1)); flat(B.p(ROOFC), offP(P, d*i), y); prism(B.p(gl), Q, y, y + dy - 0.6, false); prism(B.p(CAP), Q, y + dy - 0.6, y + dy, false); y += dy; }
  flat(B.p(ROOFC), offP(P, d*n), S.H);
};
const GLB = (c, fh, cw) => ({c, m:1, fh:fh || 4.2, cw:cw || 3.0});
const MULS = {c:'#cfd4d6', m:0, lk:0.3, lc:'#eaf2ff'}, SPS = {c:'#9aa4aa', m:0, lk:0.2};
// residential towers: light rendered spandrels / balcony edges every floor, window glass between, warm lit windows
const RESW = {c:'#e3ddd1', m:0, lk:0.3, lc:'#fff0d8'}, RESM = {c:'#d9d3c6', m:0, lk:0.25};
const resLt = () => ({m:1, c:'#ffe9c6', k:0.55});

