// ================= Shenzhen International Exchange Center (深圳国际交流中心, by Xiangmi Lake) =================
// Design led by academician He Jingtang: an integrated, stacked multi-eave roof with tiered overhangs and two wings spreading out like a
// roc (Shenzhen's "Peng City"), Lingnan deep eaves for shade and sea breezes (bjnews). OSM w1080860977 (landuse=commercial) holds the app
// footprints: two 128 x 128 m halls at 44.8 m (OSM w1431482482 / w1431482483, 6 levels), a curved 66 m, 21-level block on the west
// (w1431884285), the 16.6 m centre block (w1572116215), the 10.8 m east block (w1572116214) and the 8.8 m west link (w1572116216), all at the
// app's heights (not verified). Modelled: each hall with stone piers and glass walls under three stacked deep eaves (overhangs 7 / 5 / 3 m,
// light metal fascias, timber-toned soffits), the curved block with an eave line every four storeys and a deep crown eave, the low blocks
// with one eave. The eave depths, colours, wall rhythm and roof tiers are estimates that follow the description. The small app pieces round
// the edge of the site (guard houses) are left to the app unless they fall inside the model's hull.
LANDMARKS.szexchange = {zh:'深圳国际交流中心', en:'Shenzhen International Exchange Center', cat:'new', r:240, h:66.1, lt:{m:0, c:'#ffe2b0', k:0.85},
  build(){
    const g = new THREE.Group(), B = mkB(), E = D.szexchange, all = [[E.h, E.T]].concat(E.X);
    const PIER = {c:'#d9d4c8', m:0, lk:0.4, lc:'#ffe9c8'}, GLW = {c:'#5b6c74', m:1, fh:5, cw:3, glow:'#ffe2b8', gk:0.25}, FAS = {c:'#e4e2dc', m:0, lk:0.55, lc:'#fff1d8'},
      SOF = {c:'#a07c5a', glow:'#ffcf96', gk:0.35}, RF = '#9da3a3', HGL = {c:'#62757f', m:1, fh:3.15, cw:1.8};
    const big = all.filter(([h, R]) => h >= 8.5 && Math.abs(area2(R)) > 1000), H0 = hullP([].concat(...big.map(([, R]) => R)));
    const parts = all.filter(([h, R]) => big.some(b => b[1] === R) || pointIn(cenP(R), H0));
    // an eave plate round P at y: overhang d, fascia height fh, soffit below
    const eave = (P, y, d, fh) => { const Q = offP(P, -d); prism(B.p(FAS), Q, y - fh, y, false); flat(B.p(RF), Q, y); flat(B.p(SOF), Q, y - fh); };
    for (const [h, R] of parts){
      prism(B.p(STONE), offP(R, -0.3), -12, 0.4);     // the ground under the footprints falls ~7 m from east to west: deep plinths
      if (h > 60){ // the curved 21-level block: glass storeys, an eave every four storeys, the crown eave
        prism(B.p(HGL), offP(R, 0.4), 0.4, h - 3, false); finsP(B.p(PIER), R, 0.4, h - 3, 6.3, 0.6, 0.3, 0.6);
        for (let y = 12.6; y < h - 6; y += 12.6) eave(R, y, 1.4, 0.7);
        flat(B.p(ROOFC), R, h - 3); eave(R, h, 3.5, 1.4); prism(B.p(PLANT), offP(R, 4), h - 3, h - 0.2);
      } else if (h > 40){ // the two halls: walls to h - 12, three stacked eaves with recessed glazed clerestories between
        const yw = h - 12; prism(B.p(GLW), offP(R, 2), 0.4, yw, false); finsP(B.p(PIER), offP(R, 0.8), 0.4, yw, 8, 1.2, 0.6, 2);
        eave(R, yw, 7, 1.6);
        const R2 = offP(R, 6), R3 = offP(R, 12);
        prism(B.p(GLW), offP(R2, 1), yw, yw + 5.4, false); eave(R2, yw + 6, 5, 1.2);
        prism(B.p(GLW), offP(R3, 1), yw + 6, yw + 11.4, false); eave(R3, h, 3, 1.0);
        flat(B.p(RF), offP(R3, 1), h - 0.5);
      } else { // low blocks: glass and stone piers under one eave
        prism(B.p(GLW), offP(R, 0.6), 0.4, h - 1, false); finsP(B.p(PIER), R, 0.4, h - 1, 6, 0.5, 0.3, 0.6);
        eave(R, h, h > 9 ? 2.5 : 1.2, 0.9); flat(B.p(ROOFC), R, h - 1);
      }
    }
    B.flush(g);
    return g;
  }};
place('szexchange');

// ================= Futian Culture Square (福田区文化广场) =================
// District culture building, OSM w779037738 (63 x 42 m, a rectangle with a half-round west end); no verified height: the app's 23.4 m is
// used. Modelled: four storeys of glass behind light stone piers, horizontal louvre bands, the round end fully glazed, a planted roof. The
// storey count, facade rhythm and colours are estimates.
